<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= html_escape($title); ?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/css/tabler-icons.min.css"><style>body{background:#101831;color:#fff}.shell{max-width:950px;margin:auto;padding:30px 16px}.hero-card{background:linear-gradient(135deg,#49358f,#1b708e);border-radius:22px;padding:25px}.panel{background:#fff;color:#18223b;border-radius:17px;padding:22px;margin-top:18px}.avatars,.classes,.items{display:flex;gap:10px;flex-wrap:wrap}.pick input{display:none}.pick span{display:block;border:2px solid #ddd;border-radius:12px;padding:12px;cursor:pointer}.avatars span{font-size:35px}.pick input:checked+span{border-color:#7258c2;background:#eee8ff;box-shadow:0 0 0 3px #7258c230}.item{padding:10px;background:#f2eefc;border-radius:10px}.mastery{display:flex;justify-content:space-between;border-bottom:1px solid #eee;padding:8px}</style></head><body><main class="shell"><a class="text-white" href="<?= base_url('belajar/english-quest'); ?>"><i class="ti ti-arrow-left"></i> Peta Dunia</a><section class="hero-card mt-3"><div class="d-flex align-items-center gap-3"><div style="font-size:75px"><?= html_escape($profile['avatar']); ?></div><div><small>HERO PROFILE</small><h1><?= html_escape($profile['hero_name']); ?></h1><div>🔥 <?= (int)$profile['streak_days']; ?> hari streak · Rekor <?= (int)$profile['longest_streak']; ?> hari</div><div>✅ <?= (int)$profile['total_correct']; ?> benar · ❌ <?= (int)$profile['total_wrong']; ?> salah</div></div></div></section><?php if($this->session->flashdata('success')): ?><div class="alert alert-success mt-3"><?= html_escape($this->session->flashdata('success')); ?></div><?php endif; ?><section class="panel"><h2>Atur Hero</h2><?= form_open('belajar/english-quest/hero/save'); ?><label class="form-label">Nama Hero</label><input class="form-control mb-3" name="hero_name" maxlength="80" value="<?= html_escape($profile['hero_name']); ?>" required><label class="form-label">Avatar</label><div class="avatars mb-3"><?php foreach(['🧝','🧙','🛡️','🏹','🎵','🐲'] as $a): ?><label class="pick"><input type="radio" name="avatar" value="<?= $a; ?>" <?= $profile['avatar']===$a?'checked':''; ?>><span><?= $a; ?></span></label><?php endforeach; ?></div><label class="form-label">Character Class</label><div class="classes mb-3"><?php $classes=['word_knight'=>['⚔️','Word Knight','Ahli kosakata'],'grammar_mage'=>['🪄','Grammar Mage','Ahli struktur kalimat'],'listening_ranger'=>['🏹','Listening Ranger','Ahli pendengaran'],'speaking_bard'=>['🎵','Speaking Bard','Ahli pelafalan']];foreach($classes as $code=>$c): ?><label class="pick flex-fill"><input type="radio" name="class_code" value="<?= $code; ?>" <?= $profile['class_code']===$code?'checked':''; ?>><span><b><?= $c[0].' '.$c[1]; ?></b><small class="d-block text-secondary"><?= $c[2]; ?></small></span></label><?php endforeach; ?></div><button class="btn btn-primary">Simpan Hero</button><?= form_close(); ?></section><div class="row"><div class="col-md-6"><section class="panel"><h2>Inventory</h2><div class="items"><?php foreach($inventory as $item): ?><div class="item"><b><?= html_escape($item['item_icon'].' '.$item['item_name']); ?></b><small class="d-block">×<?= (int)$item['quantity']; ?></small></div><?php endforeach; ?><?php if(!$inventory): ?><p class="text-secondary">Belum ada item.</p><?php endif; ?></div></section></div><div class="col-md-6"><section class="panel"><h2>Perlu Dilatih Lagi</h2><?php foreach($weak_words as $word): ?><div class="mastery"><span><b><?= html_escape($word['word']); ?></b> · <?= html_escape($word['meaning']); ?></span><span><?= (int)$word['mastery_score']; ?>%</span></div><?php endforeach; ?><?php if(!$weak_words): ?><p class="text-secondary">Mulai bermain untuk membangun profil kosakata.</p><?php endif; ?></section></div></div></main></body></html>
